#!/usr/bin/env python3
"""Encode generated transparent visit artwork as small palette/RLE firmware assets."""
import argparse
import hashlib
from itertools import groupby
from pathlib import Path
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'origin_asset/ui/visit/visit-icons.png'
OUTPUT = ROOT / 'src/assets/VisitIconsData.h'
PALETTE = [(0, 0, 0), (115, 226, 183), (54, 91, 80), (226, 238, 233),
           (248, 210, 105), (183, 135, 49), (24, 38, 45), (85, 185, 155), (177, 200, 191)]
FRAMES = [('DOOR', 0, 0, 48, 48), ('PAWS', 1, 0, 48, 48),
          ('VISITOR', 0, 1, 96, 64), ('WARNING', 1, 1, 64, 64)]


def encode():
    image = Image.open(SOURCE).convert('RGBA')
    cell_w, cell_h = image.width // 2, image.height // 2
    records, data = [], []
    for name, col, row, width, height in FRAMES:
        cell = image.crop((col * cell_w, row * cell_h, (col + 1) * cell_w, (row + 1) * cell_h))
        bounds = cell.getchannel('A').point(lambda alpha: 255 if alpha >= 192 else 0).getbbox()
        if not bounds:
            raise ValueError(f'Empty generated icon: {name}')
        cell = cell.crop(bounds)
        scale = min((width - 4) / cell.width, (height - 4) / cell.height)
        cell = cell.resize((max(1, round(cell.width * scale)), max(1, round(cell.height * scale))),
                           Image.Resampling.NEAREST)
        canvas = Image.new('RGBA', (width, height))
        canvas.paste(cell, ((width - cell.width) // 2, (height - cell.height) // 2))
        indices = []
        pixels = canvas.tobytes()
        for offset in range(0, len(pixels), 4):
            red, green, blue, alpha = pixels[offset:offset + 4]
            if alpha < 192:
                indices.append(0)
            else:
                indices.append(min(range(1, len(PALETTE)),
                                   key=lambda index: sum((a - b) ** 2 for a, b in
                                                         zip((red, green, blue), PALETTE[index]))))
        if sum(index != 0 for index in indices) < 100:
            raise ValueError(f'Icon contains insufficient opaque pixels: {name}')
        start = len(data)
        for index, group in groupby(indices):
            length = sum(1 for _ in group)
            while length:
                count = min(255, length)
                data.extend((count, index))
                length -= count
        records.append((width, height, start, len(data) - start))
    sha = hashlib.sha256(SOURCE.read_bytes()).hexdigest()
    lines = ['// Generated by tools/generate_visit_icons.py; do not edit.',
             f'// Source SHA256: {sha}', '#pragma once', '#include <cstdint>',
             'namespace VisitIcons::Data {',
             'struct Frame { uint16_t width, height, offset, length; };',
             'inline constexpr uint16_t PALETTE[] = {']
    lines.append('    ' + ', '.join(f'0x{((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3):04x}'
                                  for r, g, b in PALETTE) + '};')
    lines += ['inline constexpr Frame FRAMES[] = {']
    for record in records:
        lines.append('    {' + ', '.join(map(str, record)) + '},')
    lines += ['};', 'inline constexpr uint8_t RUNS[] = {']
    for start in range(0, len(data), 24):
        lines.append('    ' + ', '.join(map(str, data[start:start + 24])) + ',')
    lines += ['};', '} // namespace VisitIcons::Data', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    content = encode()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != content:
            raise SystemExit('Visit icon header is stale; run tools/generate_visit_icons.py')
        print('PASS generated visit icons match source artwork')
    else:
        OUTPUT.write_text(content)
        print(f'Generated {OUTPUT.relative_to(ROOT)}')


if __name__ == '__main__':
    main()
